ON CONFLICT (term_key, card_key) DO UPDATE SET
  status = 'approved',
  reviewed_at = now()
WHERE glossary_card_links.status IS DISTINCT FROM 'rejected';

INSERT INTO glossary_card_links (term_key, card_key, status, matched_text)
SELECT 'multidisciplinary_center', c.card_key, 'approved', v.matched_text
FROM directory_card_edits c
JOIN (VALUES
  (345, 'מרכז גוני – מרכז טיפול ואבחון רב תחומי לפרט ולמשפחה'),
  (346, 'מרכז ד"ר טל לתמיכה רגשית ונפשית'),
  (347, 'הכח לשנות – מכון לאבחון וייעוץ'),
  (348, 'קשת רפואה – מרכז מומחים רב תחומי (כולל מרכז נווה לטיפול בהפרעות אכילה)'),
  (349, 'המכון לטיפול בהפרעות אכילה ע"ש אפרת צוק – רעות'),
  (350, 'FYM – מרפאה רב תחומית לבריאות הנפש'),
  (351, 'א'' עד ת'' – מרכז פסיכולוגי-חינוכי'),
  (352, 'מכון דביר – Machon Dvir (Dvir Institute for Behavioral Health)'),
  (62, 'עמותת בית חם – מרפאות "דרור" לבריאות הנפש'),
  (70, 'עמך – המרכז הישראלי לתמיכה נפשית וחברתית בניצולי השואה והדור השני'),
  (353, 'חוף הגליל – המרכז לטיפול בילד, במבוגר ובמשפחה (עמותה)'),
  (354, 'תחנת העמקים – העמותה לניהול תחנת העמקים (ע"ר)'),
  (104, 'מיינדמי – MindMe, מרכז פסיכיאטרי פרטי רב-תחומי'),
  (355, 'המרפאה לבריאות הנפש לדוברי אנגלית – מרכז רפואי מעייני הישועה'),
  (300, 'טיפול יום – עמותת חיבה ומעייני הישועה')
) AS v(row_id, matched_text) ON v.row_id = c.row_id
ON CONFLICT (term_key, card_key) DO UPDATE SET
  status = 'approved',
  reviewed_at = now()
WHERE glossary_card_links.status IS DISTINCT FROM 'rejected';

